                                                  \begin{document}$${ERD}\left. (f,t\right)=\frac{1}{n}\mathop{\sum }\limits_{k=1}^{n}({{ERSP}}_{k}\left. (f,t\right)-{{Baseline}}_{k}(f))$$\end{document}ERDf,t=1n∑k=1n(ERSPkf,t−Baselinek(f))\documentclass[12pt]{minimal}
